from math import ceil, isclose

def boxes(weight, capacity):
    if weight < 0 or capacity <= 0:
        raise ValueError('geçersiz ölçü')
    return ceil(weight / capacity)

print(boxes(21, 10), boxes(0, 10))
print(isclose(1e-10, 0, abs_tol=1e-9))

from enum import Enum

class Status(Enum):
    READY = 'ready'
    DONE = 'done'

def label(raw):
    try:
        state = Status(raw)
    except ValueError:
        return 'geçersiz'
    return 'bekliyor' if state is Status.READY else 'tamamlandı'

print(label('done'))
print(label('unknown'))

import re

pattern = re.compile(r'(?P<name>[A-Za-z]+):(?P<count>[0-9]+)')
for raw in ['pen:12', 'book:3', 'pen:12x']:
    match = pattern.fullmatch(raw)
    if match is None:
        print('geçersiz')
    else:
        print(match.group('name'), int(match.group('count')) * 2)

